const entryPath=location.pathname.replace(/\/$/,'')||'/';
const cameraSupport=import('/camera-support.js');
const judgeMode=entryPath!=='/officer';
const paths={shield:'<path d="M12 3 21 6v6c0 6-9 10-9 10S3 18 3 12V6z"/><path d="m8 12 3 3 5-6"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9"/>',file:'<path d="M14 2H5v20h14V7zM14 2v6h5M8 12h8M8 16h6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',history:'<path d="M3 4v6h6M3 10a9 9 0 1 1 1 7M12 7v6l4 2"/>',chart:'<path d="M4 21V12h3v9M11 21V7h3v14M18 21V3h3v18"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3z"/>',plus:'<path d="M12 4v16M4 12h16"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3z"/><circle cx="12" cy="13" r="4"/>',check:'<path d="m5 12 4 4L19 6"/>',alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',logout:'<path d="M9 3H3v18h6M9 12h12m-4-4 4 4-4 4"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.file}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);const types={passport:'Passport',visa:'Visa',national_id:'National ID',permit:'Permit',driving_license:'Driving licence',other:'Other document',face:'Face photograph'};
const labels={draft:'In progress',awaiting_review:'Officer review',flagged:'Flagged',recapture_needed:'Recapture needed',supervisor_review:'Supervisor review',completed:'Checks passed',passed:'Passed',not_performed:'Not performed',inconclusive:'Inconclusive'};
let officer=null,caseList=[],current=null,routeVersion=0,stream=null,captureBlob=null,cameraKind='document',timer,cameraGeneration=0,uploadPending=false;
const date=s=>new Date(s).toLocaleString(undefined,{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const badge=s=>`<span class="state-badge state-${s}">${labels[s]||esc(s)}</span>`;
async function api(path,options={}){if(judgeMode)return SEEMA_JUDGE.api(path,options);const headers=options.body instanceof FormData?{}:{'Content-Type':'application/json'};const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...headers,...options.headers}});let data;try{data=await response.json()}catch{throw new Error('The server could not be reached. Please retry.')}if(!response.ok){if(response.status===401&&path!=='/me'&&path!=='/login'){officer=null;stopCamera();await loginPage();}throw new Error(data.error||'The request could not be completed.');}return data;}
function notify(msg){clearTimeout(timer);const el=$('#toast');el.textContent=msg;el.hidden=false;timer=setTimeout(()=>el.hidden=true,5500);}
function formError(form,msg){let el=form.querySelector('.form-error');if(!el){el=document.createElement('p');el.className='form-error';el.setAttribute('role','alert');form.append(el);}el.textContent=msg;}
async function busy(button,fn){const text=button.innerHTML;button.disabled=true;button.textContent='Saving…';try{await fn()}catch(e){notify(e.message)}finally{if(button.isConnected){button.disabled=false;button.innerHTML=text;}}}
function frame(){document.body.classList.remove('signed-out');$('#root').innerHTML=`<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${icon('shield')}</span><span>SeemaDrishti<small>SSB · Document screening</small></span></a><nav aria-label="Main navigation">${[['overview','home','Overview'],['new','plus','New screening'],['queue','list','Review queue'],['history','history','Case history'],['reports','chart','Reports']].map(([p,i,t])=>`<a href="#${p}" data-page="${p}" aria-label="${t}">${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-footer">${icon('lock')} Officer workspace<small>${esc(officer.checkpoint)}</small></div></aside><div class="workspace"><header class="topbar"><span>SeemaDrishti <span class="header-divider">/</span><span class="header-sub">SSB document screening</span></span><button class="profile" id="profile-toggle" aria-expanded="false"><span class="avatar">${icon('user')}</span><span>${esc(officer.name)}</span><span>⌄</span></button><div class="profile-menu" id="profile-menu" hidden><strong>${esc(officer.name)}</strong><p>${esc(officer.officerCode)} · ${esc(officer.role)}</p><p>${esc(officer.checkpoint)}</p><a class="button secondary" href="${judgeMode?'/':'/judge'}">${judgeMode?'Back to prototype login':'Explore judging demo'}</a><button class="button secondary" id="logout">${icon('logout')} ${judgeMode?'Exit demo':'Log out'}</button></div></header><main><div class="environment-note ${judgeMode?'judge-banner':''}">${icon('info')}<span>${judgeMode?'<strong>JUDGING DEMO</strong> · Fictional cases. Changes reset on reload; files stay in this tab.':'SSB screening prototype · AI models and external records are not connected.'}</span>${judgeMode?'<button class="demo-reset" id="reset-demo">Reset demo</button>':''}</div><div id="app"></div></main><footer class="workspace-footer"><span>SeemaDrishti · Officer workspace</span><span>${judgeMode?'Temporary demo · No officer records accessed':'Case records are saved to your account'}</span></footer></div>`;}
function prototypeLogin(){document.body.classList.add('signed-out');$('#root').innerHTML=`<div class="login-layout"><section class="login-brand"><a class="login-logo" href="/">${icon('shield')} SeemaDrishti</a><div class="login-message"><span class="eyebrow">SSB DOCUMENT SCREENING</span><h1>Every document.<br>Every detail.<br>A clearer decision.</h1><p>Explore document capture, screening findings and officer review in one workspace.</p><div class="login-principles"><span>${icon('file')} Capture evidence</span><span>${icon('shield')} Review findings</span><span>${icon('history')} Keep a record</span></div></div><small>Detect. Verify. Protect.</small></section><section class="login-side"><div class="login-card"><span class="login-lock">${icon('user')}</span><span class="judge-tag">PUBLIC PROTOTYPE</span><h2>Officer login</h2><p>No account or password required. Leave the details blank and enter the prototype.</p><form id="prototype-login-form"><label for="demo-name">Officer name <span class="optional">optional</span></label><input id="demo-name" name="name" maxlength="100" placeholder="Demo Officer" autocomplete="off"><label for="demo-code">Officer ID <span class="optional">optional</span></label><input id="demo-code" name="officerCode" maxlength="40" placeholder="DEMO" autocomplete="off"><label for="demo-checkpoint">Checkpoint / unit <span class="optional">optional</span></label><input id="demo-checkpoint" name="checkpoint" maxlength="100" placeholder="Demo checkpoint" autocomplete="off"><button class="button full" type="submit">Enter prototype ${icon('arrow')}</button></form><section class="judge-entry"><span class="judge-tag">FOR JUDGES &amp; VISITORS</span><a class="button secondary full" href="/judge">Open demo directly ${icon('arrow')}</a></section><p class="login-footnote">This screen previews the future officer login. Demo cases are fictional; changes reset on reload.</p></div><small>SeemaDrishti · SSB screening prototype</small></section></div>`;}
async function loginPage(){document.body.classList.add('signed-out');$('#root').innerHTML=`<div class="login-layout"><section class="login-brand"><a class="login-logo" href="#">${icon('shield')} SeemaDrishti</a><div class="login-message"><span class="eyebrow">SSB DOCUMENT SCREENING</span><h1>Every document.<br>Every detail.<br>A clearer decision.</h1><p>A dedicated workspace for document capture, identity checks and officer review.</p><div class="login-principles"><span>${icon('file')} Capture evidence</span><span>${icon('shield')} Review findings</span><span>${icon('history')} Keep a record</span></div></div><small>Detect. Verify. Protect.</small></section><section class="login-side"><div class="login-card"><span class="login-lock">${icon('lock')}</span><h2>Officer sign in</h2><p>Access your saved cases and continue your screening work.</p><div id="login-content"><p class="muted">Checking account access…</p></div><section class="judge-entry"><span class="judge-tag">FOR JUDGES &amp; VISITORS</span><h3>Explore the prototype</h3><p>Open fictional cases and try the screening workflow. No account or password needed.</p><a class="button full" href="/judge">Explore judging demo ${icon('arrow')}</a></section><p class="login-footnote">Officer access uses your authorized account. An SSB identity-provider connection is pending.</p></div><small>SeemaDrishti · SSB screening prototype</small></section></div>`;
 try{const access=await api('/access');if(access.authenticated&&!access.profile&&access.canEnroll===false){$('#login-content').innerHTML='<p class="setup-note">This account is not authorized for officer access. Use the judging demo below to explore.</p>';return;}if(!access.authenticated){$('#login-content').innerHTML='<a class="button full" href="/signin-with-chatgpt?return_to=%2Fofficer" target="_top">Continue to secure sign in</a>';return;}$('#login-content').innerHTML=`<form id="login-form">${access.profile?`<div class="returning-officer"><strong>${esc(access.profile.name)}</strong><span>${esc(access.profile.officer_code)} · ${esc(access.profile.checkpoint)}</span></div>`:`<div class="setup-note">Set up your officer profile for this private preview.</div><label for="officer-name">Full name</label><input id="officer-name" name="name" autocomplete="name" required minlength="2" maxlength="100"><label for="officer-code">Officer ID</label><input id="officer-code" name="officerCode" required minlength="2" maxlength="40" placeholder="Your officer ID"><label for="checkpoint">Checkpoint / unit</label><input id="checkpoint" name="checkpoint" required maxlength="100" placeholder="Your assigned checkpoint">`}<button class="button full" type="submit">${access.profile?'Sign in to workspace':'Save profile and sign in'} ${icon('arrow')}</button></form>`;}catch(e){$('#login-content').innerHTML=`<p class="form-error" role="alert">${esc(e.message)}</p><button class="button secondary" id="retry-login">Try again</button>`;}}
function heading(title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow">OFFICER WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const newLink=`<a class="button" href="#new">${icon('plus')} New screening</a>`;
function stats(){const counts=[caseList.length,caseList.filter(c=>['awaiting_review','flagged','supervisor_review'].includes(c.status)).length,caseList.filter(c=>c.status==='recapture_needed').length,caseList.filter(c=>c.status==='completed').length];return `<div class="stats">${counts.map((n,i)=>`<div class="stat ${i===1||i===2?'amber':i===3?'green':''}"><div class="number">${n}</div><div class="stat-icon">${icon(['file','list','camera','check'][i])}</div><p>${['Saved cases','Awaiting review','Recapture needed','Checks completed'][i]}</p></div>`).join('')}</div>`;}
function empty(title,text,action=newLink){return `<div class="empty-state"><span>${icon('file')}</span><h2>${title}</h2><p>${text}</p>${action}</div>`;}
function table(list){return list.length?`<div class="table-scroll"><table><thead><tr><th>Case</th><th>Traveller</th><th>Status</th><th>Last saved</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td class="case-number">${esc(c.id)}</td><td>${esc(c.traveller_name||'Not entered')}</td><td>${badge(c.status)}</td><td>${date(c.updated_at)}</td><td><a class="table-action" href="#case/${c.id}">Open case</a></td></tr>`).join('')}</tbody></table></div>`:empty('No cases yet','Start a screening to upload documents and capture the traveller’s face.');}
function coverage(){return `<section class="card"><div class="card-title"><h2>Screening capabilities</h2></div>${[['Document and face capture','Available',''],['Saved officer cases','Available',''],['Entered field rules','Available',''],['OCR and tampering models','Not connected','gray'],['Face matching and liveness','Not connected','gray'],['Issuer / blacklist records','Not connected','gray']].map(([label,state,tone])=>`<div class="coverage-row"><span>${label}</span><span class="coverage-state"><i class="dot ${tone}"></i>${state}</span></div>`).join('')}</section>`;}
function overview(){const recent=caseList[0];return heading('Screening overview',`${judgeMode?'Explore the screening workflow with fictional sample cases.':`Welcome back, ${esc(officer.name)}. Your saved work is ready.`}`,newLink)+stats()+`${recent?`<div class="resume-card"><div><span class="eyebrow">LAST SAVED CASE</span><strong>${esc(recent.id)} <span>${esc(recent.traveller_name||'Traveller details pending')}</span></strong><p>${date(recent.updated_at)} · ${labels[recent.status]}</p></div><a class="button secondary" href="#case/${recent.id}">Resume case ${icon('arrow')}</a></div>`:''}<div class="overview-grid"><section class="card"><div class="card-title"><h2>Recent cases</h2><a class="button text" href="#queue">View queue</a></div>${table(caseList.slice(0,5))}</section><div>${coverage()}<div class="info-note">${icon('info')}<div><h3>Evidence supports the officer’s decision.</h3><p>Incomplete checks remain visible. Record a reason for every review action.</p></div></div></div></div>`;}
function newCase(){return heading('Start a screening','Create a case before collecting documents and a live face capture.')+`<section class="card new-case-card"><form id="new-case-form" class="padded"><h2>Case details</h2><p class="muted">Traveller details can be completed after capturing the documents.</p><label for="traveller">Traveller name <span class="optional">optional</span></label><input id="traveller" name="travellerName" maxlength="150" placeholder="Name as written on the document"><label for="reference">Submission / reference number <span class="optional">optional</span></label><input id="reference" name="reference" maxlength="100" placeholder="Existing submission reference, if available"><fieldset class="entry-method"><legend>How would you like to start?</legend><label class="radio-option"><input type="radio" name="entryMode" value="document" checked>Upload or capture a preferred document</label><label class="radio-option"><input type="radio" name="entryMode" value="manual">Enter civilian details manually</label><p class="fineprint">Use manual entry when a document is unavailable or the civilian needs to state their details. Both options stay available in the case.</p></fieldset><div class="form-summary">${icon('user')} Assigned to ${esc(officer.name)} · ${esc(officer.checkpoint)}</div><button class="button" type="submit">Create case and continue ${icon('arrow')}</button></form></section>`;}
function queue(history=false){return heading(history?'Case history':'Review queue',history?'Saved screening cases and their recorded actions.':'Open a case to review evidence or continue screening.',newLink)+`<section class="card"><div class="toolbar"><input class="search" id="case-search" placeholder="Search case or traveller" aria-label="Search cases"><select class="select" id="status-filter" aria-label="Filter case status"><option value="">All cases</option>${Object.entries(labels).filter(([k])=>['draft','awaiting_review','flagged','recapture_needed','supervisor_review','completed'].includes(k)).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><div id="case-table">${table(caseList)}</div></section>`;}
function reports(){return heading(officer.role==='supervisor'?'Supervisor reports':'Screening reports','Counts calculated from your authorized saved cases.')+stats()+`<div class="report-grid"><section class="card padded"><h2>Case status</h2>${['draft','awaiting_review','flagged','recapture_needed','supervisor_review','completed'].map(state=>{const count=caseList.filter(c=>c.status===state).length;return `<div class="bar-row"><span>${labels[state]}</span><div class="bar-track"><span style="width:${caseList.length?count/caseList.length*100:0}%"></span></div><strong>${count}</strong></div>`}).join('')}</section>${coverage()}</div>`;}
function preview(c){if(c.fixture)return `<div class="demo-fixture demo-${c.fixture}"><img src="/demo/document.jpg" alt="Fictional ${esc(c.fixture)} specimen"><span>FICTIONAL SAMPLE</span></div>`;return c.mime==='application/pdf'?`<a class="pdf-preview" href="${c.url}" target="_blank" rel="noopener">${icon('file')}<span>PDF document</span><small>Open saved document ↗</small></a>`:`<a class="capture-preview" href="${c.url}" target="_blank" rel="noopener"><img src="${c.url}" alt="${esc(types[c.document_type]||'Document')} capture"><span>View original ↗</span></a>`;}
function captureCard(c){return `<article class="saved-capture"><div class="saved-capture-title"><strong>${esc(types[c.document_type])}</strong><span>${esc(c.source)}</span></div>${preview(c)}<div class="capture-meta"><span>${esc(c.filename)}</span><small>${date(c.created_at)} · ${(c.size/1024).toFixed(0)} KB</small></div></article>`;}
function caseHeading(stage){const c=current.case;return `<div class="page-heading"><div><div class="eyebrow"><a href="#queue">Cases</a> / ${esc(c.id)}</div><div class="heading-inline"><h1>${{details:'Civilian details',documents:'Capture documents',face:'Capture live face',review:'Review screening'}[stage]}</h1>${badge(c.status)}</div><p>${esc(c.traveller_name||'Traveller details pending')} · ${esc(c.reference||'No submission reference')}</p></div></div><div class="workflow-steps">${[['details','1','Civilian details'],['documents','2','Documents'],['face','3','Face capture'],['review','4','Review']].map(([key,n,label])=>`<button class="workflow-step ${stage===key?'active':''}" data-stage="${key}"><b>${n}</b>${label}</button>`).join('')}<span>Saved ${date(c.updated_at)}</span></div>`;}
const civilianLabels={fullName:'Full name',birthDate:'Date of birth',nationality:'Nationality',gender:'Gender',residence:'Address / place of residence',contact:'Contact (optional)',travelPurpose:'Purpose of travel',documentType:'Preferred document type',documentNumber:'Document number',statement:'Civilian statement',officerNotes:'Officer observations'};
function civilianSummary(){const c=current.civilian;return `<section class="card padded civilian-summary"><div class="card-inline-heading"><h2>Civilian details</h2><button class="button secondary" data-stage="details">${c?'Edit details':'Add details'}</button></div>${c?`<p class="source-label">Unverified · ${c.source==='civilian_statement'?'Stated by civilian; recorded by officer':'Transcribed by officer from a document'}</p><dl class="civilian-values">${Object.entries(civilianLabels).filter(([k])=>c[k]).map(([k,label])=>`<div><dt>${label}</dt><dd>${esc(c[k])}</dd></div>`).join('')}</dl>`:'<p class="muted">No civilian statement or profile has been recorded.</p>'}</section>`;}
function details(){const c=current.civilian||{};return caseHeading('details')+`<section class="card padded"><h2>Record civilian information</h2><p class="muted">Enter information from their preferred document, or record what the civilian states. These details remain unverified and do not replace document evidence.</p><form id="civilian-form"><label for="civilian-source">Information source</label><select id="civilian-source" name="source" class="full-select"><option value="civilian_statement" ${c.source!=='document_transcription'?'selected':''}>Stated by civilian · officer records manually</option><option value="document_transcription" ${c.source==='document_transcription'?'selected':''}>Officer transcribes a submitted document</option></select><div class="field-input-grid">${Object.entries(civilianLabels).filter(([k])=>!['statement','officerNotes','documentType'].includes(k)).map(([k,label])=>`<div><label for="civilian-${k}">${label}${k==='fullName'?' *':''}</label><input id="civilian-${k}" name="${k}" type="${k==='birthDate'?'date':k==='contact'?'tel':'text'}" value="${esc(c[k]||'')}" maxlength="${['residence','travelPurpose'].includes(k)?300:k==='fullName'?150:100}" ${k==='fullName'?'required':''} ${k==='birthDate'?'max="'+new Date().toISOString().slice(0,10)+'"':''}></div>`).join('')}<div><label for="civilian-documentType">Preferred document type</label><select id="civilian-documentType" name="documentType" class="full-select"><option value="">Not available / not stated</option>${Object.entries(types).filter(([k])=>k!=='face').map(([k,label])=>`<option value="${k}" ${c.documentType===k?'selected':''}>${label}</option>`).join('')}</select></div></div><label for="civilian-statement">Civilian statement</label><textarea id="civilian-statement" name="statement" maxlength="1500" rows="3" placeholder="Record the civilian’s explanation in their own words where possible.">${esc(c.statement||'')}</textarea><label for="civilian-notes">Officer observations</label><textarea id="civilian-notes" name="officerNotes" maxlength="1500" rows="3" placeholder="Record missing documents, communication needs or follow-up questions.">${esc(c.officerNotes||'')}</textarea><p class="fineprint">A recorded statement is not proof of identity. If the name cannot be established, enter Unknown and explain in the observations.</p><button type="submit" class="button">Save civilian details</button></form></section><div class="page-actions"><button class="button secondary" id="save-return">Save and return to overview</button><button class="button" data-stage="documents">Save and add preferred document ${icon('arrow')}</button></div>`;}
function fieldsForm(){const f=current.fields;return `<section class="card padded"><h2>Document information</h2><p class="muted">Enter values from the source documents. OCR is not connected yet.</p><form id="fields-form"><div class="field-input-grid">${[['passportName','Passport name','text'],['passportNumber','Passport number','text'],['nationality','Nationality','text'],['passportDob','Passport birth date','date'],['passportExpiry','Passport expiry','date'],['visaName','Visa name','text'],['visaNumber','Visa number','text'],['visaDob','Visa birth date','date'],['visaType','Visa type','text'],['visaExpiry','Visa expiry','date']].map(([key,label,type])=>`<div><label for="field-${key}">${label}</label><input id="field-${key}" name="${key}" type="${type}" maxlength="150" value="${esc(f[key]||'')}"></div>`).join('')}</div><div class="section-actions"><span class="source-label">Source: officer entry</span><button class="button secondary" type="submit">Save document information</button></div></form></section>`;}
function documents(){const docs=current.captures.filter(c=>c.kind==='document'&&!c.superseded);return caseHeading('documents')+`<div class="info-note">${icon('info')}<div><h3>Document upload or manual details</h3><p>Attach any supported document below. You can also record the civilian’s stated details manually.</p><button class="button secondary" data-stage="details">Enter civilian details</button></div></div><div class="capture-layout"><section class="card padded"><h2>Add a document</h2><label for="document-type">Document type</label><select id="document-type" class="full-select">${Object.entries(types).filter(([k])=>k!=='face').map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><div class="upload-zone" id="dropzone"><span>${icon('upload')}</span><h3>Upload a document</h3><p>Drop a file here, or choose one from this device.</p><button class="button" id="upload-document">Choose file</button><small>JPEG, PNG, WebP or PDF · Up to 12 MB</small></div><div class="capture-alternatives"><button class="button secondary" data-camera="document">${icon('camera')} Use camera</button><button class="button secondary" id="import-scan">${icon('file')} Import scanner file</button></div><p class="fineprint">For a scanner, scan using its device software and import the saved file. Direct scanner control is not connected.</p><input id="document-file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf" hidden><div id="upload-feedback" role="status"></div></section><section class="card padded"><div class="card-inline-heading"><h2>Saved documents</h2><span class="source-label">${docs.length} active</span></div>${docs.length?`<div class="saved-captures">${docs.map(captureCard).join('')}</div>`:empty('No documents added','Upload or capture the traveller’s first document.','')}<p class="fineprint">A new capture of the same document type replaces the active version. Earlier captures stay in the case record.</p></section></div>${fieldsForm()}<div class="page-actions"><button class="button secondary" id="save-return">Save and return to overview</button><button class="button" data-stage="face">Continue to face capture ${icon('arrow')}</button></div>`;}
function face(){const face=current.captures.find(c=>c.kind==='face'&&!c.superseded),passport=current.captures.find(c=>c.document_type==='passport'&&!c.superseded);return caseHeading('face')+`<div class="capture-layout"><section class="card padded"><h2>Face photograph</h2><p class="muted">Capture the person present at the checkpoint.</p>${face?captureCard(face):`<div class="face-placeholder">${icon('user')}<h3>No face capture saved</h3><p>Ask the traveller to face the camera with their face clearly visible.</p></div>`}<button class="button full" data-camera="face">${icon('camera')} ${face?'Retake face photograph':'Open camera'}</button><p class="fineprint">Face comparison and liveness checks are not connected. Saving a photograph does not complete these checks.</p></section><section class="card padded"><h2>Document reference</h2><p class="muted">The passport will provide the reference portrait for face comparison.</p>${passport?captureCard(passport):empty('Passport not added','Return to Documents to add a passport.','')}<div class="info-note">${icon('info')}<div><h3>Keep the capture clear.</h3><p>Use even lighting, keep the face unobstructed, and retake blurred images.</p></div></div></section></div><div class="page-actions"><button class="button secondary" data-stage="documents">Back to documents</button><button class="button" id="evaluate-checks">Evaluate available checks ${icon('arrow')}</button></div>`;}
function review(){const active=current.captures.filter(c=>!c.superseded);return caseHeading('review')+civilianSummary()+`<div class="alert"><span>${icon('info')}</span><div><h3>${current.checksStale?'Inputs changed — refresh the checks':current.run?'Review evidence and incomplete checks':'Checks have not been evaluated'}</h3><p>${current.checksStale?'The saved results refer to an earlier capture or field entry.': 'AI and external checks remain not performed. The case cannot be marked passed while required checks are incomplete.'}</p></div><button class="button secondary" id="evaluate-checks">${current.run?'Refresh checks':'Evaluate available checks'}</button></div><div class="review-grid"><div><section class="card padded"><h2>Case evidence</h2>${active.length?`<div class="evidence-gallery">${active.map(captureCard).join('')}</div>`:empty('No evidence saved','Add documents and a live face capture before screening.','')}</section><section class="card checks-section"><div class="card-title"><h2>Check results</h2><span class="source-label">${current.run?date(current.run.created_at):'Not evaluated'}</span></div>${current.checks.length?current.checks.map(c=>`<div class="result-row"><div><strong>${esc(c.label)}</strong><p>${esc(c.detail)}</p><small>${esc(c.basis)}</small></div>${badge(current.checksStale?'inconclusive':c.state)}</div>`).join(''):'<div class="empty">Evaluate available checks to see results.</div>'}</section></div><section class="card padded action-panel"><form id="decision-form"><h2>Officer action</h2><p class="muted">Review the source evidence and record the next step.</p>${[['recapture','Request another capture'],['supervisor','Refer for supervisor review'],['note','Record review note']].map(([v,t],i)=>`<label class="radio-option"><input type="radio" name="action" value="${v}" ${i===1?'checked':''}>${t}</label>`).join('')}<label class="radio-option disabled"><input type="radio" disabled>Mark checks passed</label><p class="fineprint">Unavailable until every required check passes.</p><div class="reason-block"><label for="reason">Reason for action</label><textarea id="reason" name="reason" required minlength="5" maxlength="1000" rows="5" placeholder="Record the evidence reviewed and the follow-up required."></textarea></div><button type="submit" class="button full">Record officer action</button><p class="fineprint">This records a screening action, not travel clearance. Supervisor referrals remain pending until reviewed by an authorized supervisor.</p></form></section></div><section class="card history-card"><h2>Case activity</h2><div class="activity-list">${current.events.map(e=>`<div><span class="activity-dot"></span><section><strong>${esc(e.action)}</strong><p>${esc(e.detail)}</p><small>${date(e.created_at)} · ${esc(e.officer_name)}</small></section></div>`).join('')}</div></section>${current.captures.some(c=>c.superseded)?`<details class="card padded prior-captures"><summary>Earlier capture versions</summary><div class="evidence-gallery">${current.captures.filter(c=>c.superseded).map(captureCard).join('')}</div></details>`:''}`;}
async function render(){if(!officer)return;stopCamera();const version=++routeVersion;const [page='overview',caseId,requestedStage]=location.hash.slice(1).split('/');document.querySelectorAll('nav a').forEach(a=>{const selected=a.dataset.page===(page==='case'?'queue':page);a.classList.toggle('active',selected);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#app').innerHTML='<div class="loading-state">Loading saved workspace…</div>';try{if(page==='case'){const data=await api('/cases/'+encodeURIComponent(caseId));if(version!==routeVersion)return;current=data;const stage=['details','documents','face','review'].includes(requestedStage)?requestedStage:current.case.stage;$('#app').innerHTML=({details,documents,face,review}[stage]||documents)();}else{const data=await api('/cases');if(version!==routeVersion)return;caseList=data.cases;$('#app').innerHTML=({overview,new:newCase,queue,history:()=>queue(true),reports}[page]||overview)();}document.title='SeemaDrishti | Officer workspace';window.scrollTo(0,0);}catch(e){if(officer&&version===routeVersion)$('#app').innerHTML=`<div class="card padded"><h2>Unable to load this page</h2><p class="form-error">${esc(e.message)}</p><button class="button secondary" id="retry-page">Try again</button></div>`;}}
function stopCamera(){cameraGeneration++;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;captureBlob=null;const video=$('#camera-video');if(video)video.srcObject=null;const dialog=$('#camera-dialog');if(dialog?.open)dialog.close();}
async function openCamera(kind,deviceId){const generation=++cameraGeneration;cameraKind=kind;const dialog=$('#camera-dialog');if(!dialog.open)dialog.showModal();$('#camera-heading').textContent=kind==='face'?'Capture face photograph':'Capture document';$('#camera-error').textContent='';$('#camera-status').textContent='Allow camera access when your browser asks.';$('#save-capture').disabled=true;$('#take-photo').disabled=true;$('#take-photo').textContent='Take photo';$('#camera-photo').hidden=true;$('#camera-video').hidden=false;captureBlob=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#camera-device').disabled=true;$('#camera-device').innerHTML='<option>Connecting camera…</option>';$('#camera-device-input').setAttribute('capture',kind==='face'?'user':'environment');$('#camera-direct').href=location.origin+(judgeMode?'/judge':location.pathname+location.hash);$('#camera-help').hidden=false;const context={secure:window.isSecureContext,supported:!!navigator.mediaDevices?.getUserMedia,policyAllowed:(document.permissionsPolicy||document.featurePolicy)?.allowsFeature?.('camera')!==false,embedded:window.self!==window.top};const support=await cameraSupport;try{if(!context.secure||!context.supported||!context.policyAllowed)throw new Error('Camera unavailable');const nextStream=await support.requestCamera(navigator.mediaDevices,kind,deviceId);if(generation!==cameraGeneration){nextStream.getTracks().forEach(t=>t.stop());return;}stream=nextStream;$('#camera-video').srcObject=stream;await $('#camera-video').play();if(generation!==cameraGeneration)return;$('#take-photo').disabled=false;$('#camera-status').textContent='Camera connected. Position the subject and take a photograph.';$('#camera-help').hidden=true;let devices=[];try{devices=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='videoinput')}catch{}if(generation!==cameraGeneration)return;const currentDevice=stream.getVideoTracks()[0]?.getSettings().deviceId;$('#camera-device').innerHTML=devices.length?devices.map((d,i)=>`<option value="${esc(d.deviceId)}" ${d.deviceId===currentDevice?'selected':''}>${esc(d.label||'Camera '+(i+1))}</option>`).join(''):'<option>Default camera</option>';$('#camera-device').disabled=!devices.length;}catch(e){if(generation!==cameraGeneration)return;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#camera-video').srcObject=null;$('#camera-status').textContent='Camera not connected';$('#camera-error').textContent=support.cameraProblem(e,context);$('#camera-device').innerHTML='<option>No active camera</option>';$('#camera-help').hidden=false;}}
async function saveUpload(file,source,kind='document'){if(!file)return;if(uploadPending)throw new Error('A capture is already being saved. Please wait.');uploadPending=true;try{if(file.size>12*1024*1024)throw new Error('Choose a file smaller than 12 MB.');const data=new FormData();data.append('file',file,file.name||`${kind}-${Date.now()}.jpg`);data.append('kind',kind);data.append('source',source);data.append('documentType',kind==='face'?'face':$('#document-type')?.value||'passport');await api('/cases/'+current.case.id+'/captures',{method:'POST',body:data});notify(kind==='face'?'Live face capture saved.':'Document saved to the case.');await render();}finally{uploadPending=false;}}
async function persistFields(){const civilianForm=$('#civilian-form');if(civilianForm){if(!civilianForm.reportValidity())throw new Error('Complete the required civilian details before continuing.');await api('/cases/'+current.case.id+'/civilian',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(civilianForm)))});}const form=$('#fields-form');if(form)await api('/cases/'+current.case.id+'/fields',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});}
async function stage(key){await persistFields();await api('/cases/'+current.case.id+'/stage',{method:'POST',body:JSON.stringify({stage:key})});location.hash=`case/${current.case.id}/${key}`;}
document.addEventListener('submit',async e=>{const form=e.target;if(!['prototype-login-form','login-form','new-case-form','fields-form','civilian-form','decision-form'].includes(form.id))return;e.preventDefault();const button=form.querySelector('button[type="submit"]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));if(form.id==='prototype-login-form'){officer={...SEEMA_JUDGE.officer,name:data.name.trim()||'Demo Officer',officerCode:data.officerCode.trim()||'DEMO',checkpoint:data.checkpoint.trim()||'Demo checkpoint'};frame();location.hash='overview';await render();return;}if(form.id==='login-form'){const result=await api('/login',{method:'POST',body:JSON.stringify(data)});officer=result.officer;frame();if(!location.hash||location.hash==='#login')location.hash='overview';await render();}if(form.id==='new-case-form'){const result=await api('/cases',{method:'POST',body:JSON.stringify(data)});location.hash='case/'+result.id+(data.entryMode==='manual'?'/details':'/documents');}if(form.id==='civilian-form'){await api('/cases/'+current.case.id+'/civilian',{method:'POST',body:JSON.stringify(data)});notify('Civilian details saved as unverified.');await render();}if(form.id==='fields-form'){await api('/cases/'+current.case.id+'/fields',{method:'POST',body:JSON.stringify(data)});notify('Document information saved.');await render();}if(form.id==='decision-form'){await api('/cases/'+current.case.id+'/decision',{method:'POST',body:JSON.stringify(data)});notify('Officer action saved to the case history.');await render();}}catch(err){if(form.isConnected)formError(form,err.message)}finally{if(button.isConnected)button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='reset-demo'){location.reload();return;}if(b.id==='logout'&&judgeMode){location.href='/';return;}if(b.id==='retry-login')return loginPage();if(b.id==='retry-page')return render();if(b.id==='profile-toggle'){const menu=$('#profile-menu');menu.hidden=!menu.hidden;b.setAttribute('aria-expanded',String(!menu.hidden));}if(b.id==='logout')await busy(b,async()=>{await api('/logout',{method:'POST',body:'{}'});officer=null;stopCamera();location.hash='login';if(['localhost','127.0.0.1'].includes(location.hostname))await loginPage();else location.href='/signout-with-chatgpt?return_to=%2F';});if(b.id==='save-return')await busy(b,async()=>{await persistFields();location.hash='overview';});if(b.dataset.stage)await busy(b,()=>stage(b.dataset.stage));if(b.id==='upload-document'||b.id==='import-scan'){$('#document-file').dataset.source=b.id==='import-scan'?'scanner':'upload';$('#document-file').click();}if(b.dataset.camera)await openCamera(b.dataset.camera);if(b.id==='camera-device-open'){cameraGeneration++;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;$('#camera-device-input').value='';$('#camera-device-input').click();}if(b.id==='camera-retry')await openCamera(cameraKind);if(b.id==='camera-close')stopCamera();if(b.id==='take-photo'){if(captureBlob){captureBlob=null;$('#camera-photo').hidden=true;$('#camera-video').hidden=false;$('#save-capture').disabled=true;b.textContent='Take photo';return;}const video=$('#camera-video');if(!video.videoWidth){$('#camera-error').textContent='Wait for the camera image, then capture again.';return;}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);canvas.toBlob(blob=>{captureBlob=blob;$('#camera-photo').src=canvas.toDataURL('image/jpeg',.9);$('#camera-photo').hidden=false;$('#camera-video').hidden=true;$('#save-capture').disabled=false;$('#take-photo').textContent='Retake photo';},'image/jpeg',.9);}if(b.id==='save-capture')await busy(b,async()=>{if(!captureBlob)throw new Error('Capture a photograph first.');await saveUpload(captureBlob,captureBlob instanceof File?'device_camera':'camera',cameraKind);stopCamera();});if(b.id==='evaluate-checks')await busy(b,async()=>{const d=await api('/cases/'+current.case.id+'/checks',{method:'POST',body:'{}'});current=d;if(location.hash.endsWith('/review'))await render();else location.hash='case/'+current.case.id+'/review';notify('Available checks evaluated. Unconnected checks remain not performed.');});});
document.addEventListener('change',async e=>{if(e.target.id==='camera-device-input'){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){$('#camera-error').textContent='Choose a JPEG, PNG or WebP photograph.';return;}if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;captureBlob=file;$('#camera-photo').src=URL.createObjectURL(file);$('#camera-photo').hidden=false;$('#camera-video').hidden=true;$('#camera-status').textContent='Device photograph ready. This is not a liveness check.';$('#camera-error').textContent='';$('#take-photo').disabled=true;$('#save-capture').disabled=false;return;}if(e.target.id==='document-file'){const feedback=$('#upload-feedback');feedback.textContent='Uploading and saving document…';try{await saveUpload(e.target.files[0],e.target.dataset.source||'upload')}catch(err){feedback.textContent=err.message;feedback.className='form-error';}}if(e.target.id==='camera-device')await openCamera(cameraKind,e.target.value);if(e.target.id==='status-filter')filterCases();});
function filterCases(){const q=$('#case-search').value.toLowerCase(),status=$('#status-filter').value;const list=caseList.filter(c=>(c.id+' '+c.traveller_name).toLowerCase().includes(q)&&(!status||c.status===status));$('#case-table').innerHTML=list.length?table(list):empty('No matching cases','Try another search or status filter.','');}
document.addEventListener('input',e=>{if(e.target.id==='case-search')filterCases();});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('dragging');}});document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone').classList.remove('dragging');});document.addEventListener('drop',async e=>{if(!e.target.closest('#dropzone'))return;e.preventDefault();$('#dropzone').classList.remove('dragging');const feedback=$('#upload-feedback');feedback.textContent='Uploading and saving document…';try{await saveUpload(e.dataTransfer.files[0],'upload')}catch(err){feedback.textContent=err.message;feedback.className='form-error';}});
$('#camera-dialog').addEventListener('cancel',stopCamera);window.addEventListener('pagehide',stopCamera);window.addEventListener('hashchange',()=>{if(officer)render();});
async function start(){if(judgeMode){if(entryPath==='/judge'){officer=SEEMA_JUDGE.officer;frame();await render();}else prototypeLogin();return;}try{const result=await api('/me');officer=result.officer;frame();await render();}catch{await loginPage();}}start();
